// async-futures | concurrent-accumulate / std-async | single / p1

#include <future>
#include <iostream>
#include <vector>

int triangular(int value) {
    long long total = 0;
    for (int i = 1; i <= value; i++) total += i;
    return static_cast<int>(total);
}

int main() {
    std::vector<std::future<int>> futures;
    futures.reserve(5);
    for (int i = 1; i <= 5; i++) {
        futures.push_back(std::async(std::launch::async, triangular, i));
    }

    long long total = 0;
    for (auto& future : futures) {
        total += future.get();
    }
    std::cout << "total=" << total << " tag=alpha" << '\n';
    return 0;
}

