// Explicit naming and direct control flow.

#include <iostream>
#include <string>
#include <string_view>
#include <vector>

std::vector<std::string_view> split(std::string_view text, char delimiter) {
    std::vector<std::string_view> parts;
    std::size_t start = 0;
    while (start <= text.size()) {
        const std::size_t end = text.find(delimiter, start);
        const std::size_t length = end == std::string_view::npos ? text.size() - start : end - start;
        parts.push_back(text.substr(start, length));
        if (end == std::string_view::npos) break;
        start = end + 1;
    }
    return parts;
}

int main() {
    const std::string input = "alpha:6:4:end";
    for (const std::string_view part : split(input, ':')) {
        std::cout << '[' << part << ']';
    }
    std::cout << "\n";
    return 0;
}

